#include "temp_sensor_temp_sensor.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void temp_sensor_temp_sensor_initialize(void);
void temp_sensor_temp_sensor_notify(microkit_channel channel);
void temp_sensor_temp_sensor_timeTriggered(void);

volatile sb_queue_Isolette_Data_Model_Temp_1_t *current_temp_queue_1;
volatile sb_queue_uint8_t_1_t *temp_changed_queue_1;

#define PORT_FROM_MON 0

bool put_current_temp(const Isolette_Data_Model_Temp *data) {
  sb_queue_Isolette_Data_Model_Temp_1_enqueue((sb_queue_Isolette_Data_Model_Temp_1_t *) current_temp_queue_1, (Isolette_Data_Model_Temp *) data);

  return true;
}

bool put_temp_changed() {
  uint8_t eventPayload = 0; // always send 0 as the event payload
  uint8_t *data = &eventPayload;
  sb_queue_uint8_t_1_enqueue((sb_queue_uint8_t_1_t *) temp_changed_queue_1, (uint8_t *) data);

  return true;
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_Isolette_Data_Model_Temp_1_init((sb_queue_Isolette_Data_Model_Temp_1_t *) current_temp_queue_1);

  sb_queue_uint8_t_1_init((sb_queue_uint8_t_1_t *) temp_changed_queue_1);

  temp_sensor_temp_sensor_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      temp_sensor_temp_sensor_timeTriggered();
      // Report that this dispatch has finished.  The _MON wrapper forwards it to
      // the scheduler.  The default scheduler ignores runtime signals from
      // partitions -- the schedule is static and each partition runs for its full
      // allotted time -- so this is inert there; the test scheduler uses it as the
      // slot-complete event, which is what lets it step as fast as threads run
      // rather than waiting out each slot's wall-clock budget.
      microkit_notify(PORT_FROM_MON);
      break;
    default:
      temp_sensor_temp_sensor_notify(channel);
  }
}
